-- Email payment reminders (off by default; switched on per user in Settings -> Notifications).
-- One row per reminder already sent, so the daily job never emails the same due date twice.
CREATE TABLE IF NOT EXISTS "ReminderLogs" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "UserId" text NOT NULL,
    "RefKey" varchar(60) NOT NULL,                 -- e.g. rec:12, ins:3, bill:7
    "DueDate" date NOT NULL,
    "SentAt" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "FK_ReminderLogs_Users_UserId" FOREIGN KEY ("UserId") REFERENCES identity."Users" ("Id") ON DELETE CASCADE
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_ReminderLogs_User_Ref_Due" ON "ReminderLogs" ("UserId", "RefKey", "DueDate");
